#!/usr/bin/env bash
# Generates the validation media library used by CI (all content synthetic, generated by FFmpeg).
# Layout follows Jellyfin naming so the server identifies movies, a series, seasons and episodes.
set -euo pipefail
OUT=${1:-media}
FONT=/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf
mkdir -p "$OUT/movies" "$OUT/tv/Skylark Isles/Season 01"
TMP=$(mktemp -d)

pattern() { # duration size rate [extra lavfi]
  echo "testsrc2=duration=$1:size=$2:rate=$3"
}

# ---------- subtitle sources ----------
cat > "$TMP/plain.srt" <<'SRT'
1
00:00:00,500 --> 00:00:03,000
Plain SubRip line one

2
00:00:03,200 --> 00:00:06,000
<i>Italic</i> SubRip line two
SRT

cat > "$TMP/forced.srt" <<'SRT'
1
00:00:01,000 --> 00:00:04,000
[FORCED] Sign: "Station"
SRT

cat > "$TMP/spa.srt" <<'SRT'
1
00:00:00,500 --> 00:00:05,000
Subtítulo en español
SRT

cat > "$TMP/styled.ass" <<'ASS'
[Script Info]
ScriptType: v4.00+
PlayResX: 1920
PlayResY: 1080
WrapStyle: 0

[V4+ Styles]
Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding
Style: Default,DejaVu Sans,64,&H00FFFFFF,&H000000FF,&H00101010,&H90000000,-1,0,0,0,100,100,0,0,1,3.5,2,2,80,80,60,1
Style: Top,DejaVu Sans,52,&H0000E5FF,&H000000FF,&H00000000,&H80000000,-1,-1,0,0,100,100,0,0,1,3,0,8,80,80,50,1
Style: Karaoke,DejaVu Sans,70,&H00FFFFFF,&H00FF8800,&H00000000,&H80000000,-1,0,0,0,100,100,2,0,1,4,0,2,80,80,140,1

[Events]
Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
Dialogue: 0,0:00:00.30,0:00:05.50,Default,,0,0,0,,Bottom dialogue with {\c&H66CCFF&}colour{\r} and {\i1}italics{\i0}
Dialogue: 0,0:00:00.30,0:00:05.50,Top,,0,0,0,,Simultaneous top line (alignment 8)
Dialogue: 1,0:00:01.00,0:00:05.50,Karaoke,,0,0,0,,{\k40}Ka{\k40}ra{\k40}o{\k60}ke {\k50}ef{\k50}fect
Dialogue: 2,0:00:00.50,0:00:05.50,Default,,0,0,0,,{\an7\pos(120,120)\fs40\bord2\1c&H00FF00&}\N{\an7}Positioned sign (\pos)
Dialogue: 0,0:00:06.00,0:00:11.00,Default,,0,0,0,,{\fad(400,400)}Fade in / fade out
ASS

cat > "$TMP/anime.ass" <<'ASS'
[Script Info]
ScriptType: v4.00+
PlayResX: 1920
PlayResY: 1080
ScaledBorderAndShadow: yes

[V4+ Styles]
Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding
Style: Dialogue,DejaVu Sans,62,&H00FFFFFF,&H000000FF,&H00202020,&HA0000000,-1,0,0,0,100,100,0,0,1,3.2,1.5,2,90,90,55,1
Style: Sign,DejaVu Sans,58,&H00203040,&H000000FF,&H00F0F0F0,&H00000000,-1,0,0,0,100,100,1,0,1,2,0,5,0,0,0,1
Style: OP-Romaji,DejaVu Sans,48,&H00FFFFFF,&H00C080FF,&H00602080,&H00000000,-1,0,0,0,100,100,1,0,1,2.5,0,8,40,40,40,1

[Events]
Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text
Comment: 0,0:00:00.00,0:00:00.00,Sign,,0,0,0,,--- typesetting ---
Dialogue: 5,0:00:00.20,0:00:09.80,Sign,,0,0,0,,{\an5\pos(1440,300)\frz-12\fscx110\blur0.6\bord3\3c&HFFFFFF&}Rotated Shop Sign
Dialogue: 4,0:00:00.20,0:00:09.80,Sign,,0,0,0,,{\an5\move(300,800,900,700,0,9000)\frz8\1c&H3030E0&}Moving sign (\move)
Dialogue: 6,0:00:02.00,0:00:09.80,Sign,,0,0,0,,{\an5\pos(960,540)\clip(760,480,1160,600)\t(0,3000,\frz360)\fs90\1c&H10D0FF&}CLIP+T
Dialogue: 3,0:00:00.20,0:00:09.80,OP-Romaji,,0,0,0,,{\k30}Ki{\k30}ra{\k30}me{\k50}ku {\k40}so{\k40}ra
Dialogue: 0,0:00:00.20,0:00:04.80,Dialogue,,0,0,0,,{\i1}Overlapping{\i0} line one
Dialogue: 0,0:00:01.50,0:00:06.00,Dialogue,,0,0,0,,Overlapping line two (stacks above)
Dialogue: 0,0:00:06.20,0:00:09.80,Dialogue,,0,0,0,,{\fad(300,300)\be1}Edge-blur fade
ASS

# Repeat every subtitle event every 10 s so styled subtitles are on screen for the whole clip.
repeat_events() { # file
  python3 - "$1" <<'PY'
import re, sys
p = sys.argv[1]; lines = open(p).read().split("\n")
head = [l for l in lines if not l.startswith("Dialogue:")]
ev = [l for l in lines if l.startswith("Dialogue:")]
def shift(t, s):
    h, m, rest = t.split(":"); sec = float(rest) + int(m) * 60 + int(h) * 3600 + s
    return "%d:%02d:%05.2f" % (sec // 3600, (sec % 3600) // 60, sec % 60)
out = []
for k in range(0, 4):
    for l in ev:
        f = l.split(",", 9)
        f[1] = (f[1].split(": ")[0] + ": " + shift(f[1].split(": ")[1], 10 * k)) if ": " in f[1] else shift(f[1], 10 * k)
        f[2] = shift(f[2], 10 * k)
        out.append(",".join(f))
open(p, "w").write("\n".join(head + out) + "\n")
PY
}
repeat_events "$TMP/styled.ass"
repeat_events "$TMP/anime.ass"

# ---------- 1) H.264 + AAC + embedded SRT, plus external .en.srt sidecar ----------
D="$OUT/movies/Harbor Lights (2021)"; mkdir -p "$D"
ffmpeg -nostdin -y -loglevel error -f lavfi -i "$(pattern 30 1920x1080 24)" -f lavfi -i "sine=frequency=440:duration=30" -i "$TMP/plain.srt" \
  -map 0 -map 1 -map 2 -c:v libx264 -preset veryfast -crf 26 -pix_fmt yuv420p -c:a aac -b:a 128k -c:s srt \
  -metadata:s:a:0 language=eng -metadata:s:s:0 language=eng -metadata title="Harbor Lights" "$D/Harbor Lights (2021).mkv"
cp "$TMP/plain.srt" "$D/Harbor Lights (2021).en.srt"

# ---------- 2) HEVC Main10 + AC3 5.1 + embedded styled ASS + font attachment ----------
D="$OUT/movies/Glass Meridian (2023)"; mkdir -p "$D"
ffmpeg -nostdin -y -loglevel error -f lavfi -i "$(pattern 30 1920x1080 24)" -f lavfi -i "sine=frequency=330:duration=30" -i "$TMP/styled.ass" \
  -map 0 -map 1 -map 2 -c:v libx265 -preset ultrafast -x265-params log-level=error -pix_fmt yuv420p10le -profile:v main10 \
  -c:a ac3 -ac 6 -b:a 384k -c:s ass -attach "$FONT" -metadata:s:t:0 mimetype=application/x-truetype-font -metadata:s:t:0 filename=DejaVuSans-Bold.ttf \
  -metadata:s:a:0 language=eng -metadata:s:s:0 language=eng -metadata:s:s:0 title="English (styled ASS)" "$D/Glass Meridian (2023).mkv"

# ---------- 3) MKV with multiple audio and subtitle tracks ----------
D="$OUT/movies/Seven Rivers (2019)"; mkdir -p "$D"
ffmpeg -nostdin -y -loglevel error -f lavfi -i "$(pattern 30 1280x720 25)" \
  -f lavfi -i "sine=frequency=500:duration=30" -f lavfi -i "sine=frequency=600:duration=30" -f lavfi -i "sine=frequency=700:duration=30" \
  -i "$TMP/styled.ass" -i "$TMP/forced.srt" -i "$TMP/spa.srt" \
  -map 0 -map 1 -map 2 -map 3 -map 4 -map 5 -map 6 \
  -c:v libx264 -preset veryfast -crf 28 -c:a:0 aac -ac:a:0 2 -c:a:1 ac3 -ac:a:1 6 -c:a:2 eac3 -ac:a:2 6 \
  -c:s:0 ass -c:s:1 srt -c:s:2 srt \
  -metadata:s:a:0 language=eng -metadata:s:a:0 title="English Stereo" \
  -metadata:s:a:1 language=jpn -metadata:s:a:1 title="Japanese 5.1" \
  -metadata:s:a:2 language=spa -metadata:s:a:2 title="Spanish 5.1 (E-AC3)" \
  -metadata:s:s:0 language=eng -metadata:s:s:0 title="English Full" \
  -metadata:s:s:1 language=eng -metadata:s:s:1 title="English Forced" -disposition:s:1 forced \
  -metadata:s:s:2 language=spa -metadata:s:s:2 title="Spanish" \
  "$D/Seven Rivers (2019).mkv"

# ---------- 3b) Episode-length resume test: 3 min of 1080p H.264 at ~6 Mbps, a keyframe every 10 s ----------
# Resume timing needs what real releases have and the short samples don't: long keyframe gaps,
# several MB a second, two audio tracks, ASS subtitles with embedded fonts (stored before the video).
D="$OUT/movies/Tidewater (2017)"; mkdir -p "$D"
ATTACH=(); i=0
for f in /usr/share/fonts/truetype/dejavu/DejaVuSans*.ttf; do
  [ -f "$f" ] || continue
  ATTACH+=(-attach "$f" -metadata:s:t:$i mimetype=application/x-truetype-font -metadata:s:t:$i "filename=$(basename "$f")"); i=$((i+1))
done
ffmpeg -nostdin -y -loglevel error -f lavfi -i "testsrc2=duration=180:size=1920x1080:rate=25,noise=alls=12:allf=t" \
  -f lavfi -i "sine=frequency=440:duration=180" -f lavfi -i "sine=frequency=330:duration=180" -i "$TMP/styled.ass" \
  -map 0 -map 1 -map 2 -map 3 \
  -c:v libx264 -preset veryfast -b:v 6M -maxrate 8M -bufsize 12M -pix_fmt yuv420p -x264-params keyint=250:min-keyint=250:scenecut=0 \
  -c:a:0 aac -b:a:0 192k -ac:a:0 2 -c:a:1 ac3 -b:a:1 448k -ac:a:1 6 -c:s ass "${ATTACH[@]}" \
  -metadata:s:a:0 language=eng -metadata:s:a:1 language=jpn -metadata:s:s:0 language=eng \
  "$D/Tidewater (2017).mkv"

# ---------- 3c) Anime-style release for the resume/seek repro: dense typesetting + ~40 MB of fonts ----------
# Fansub releases carry their fonts as MKV attachments ahead of the video (often 10–40 MB) and keep
# subtitles on screen almost all the time (dialogue, signs with movement/blur, karaoke).
D="$OUT/movies/Lantern Festival (2020)"; mkdir -p "$D"
python3 - "$TMP/lantern.ass" <<'PY'
import sys, random
r = random.Random(5)
def ts(t): return f"{int(t//3600)}:{int(t%3600//60):02d}:{t%60:05.2f}"
lines = ["[Script Info]", "ScriptType: v4.00+", "PlayResX: 1920", "PlayResY: 1080", "WrapStyle: 0", "",
         "[V4+ Styles]",
         "Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding",
         "Style: Default,DejaVu Sans,64,&H00FFFFFF,&H000000FF,&H00101010,&H80000000,-1,0,0,0,100,100,0,0,1,3.5,1.5,2,60,60,50,1",
         "Style: Sign,DejaVu Serif,56,&H00E0F0FF,&H000000FF,&H00402010,&H00000000,0,0,0,0,100,100,2,0,1,2,0,8,60,60,60,1",
         "Style: Karaoke,DejaVu Sans Mono,52,&H0066CCFF,&H00FFFFFF,&H00000000,&H00000000,-1,0,0,0,100,100,0,0,1,2,1,8,60,60,30,1", "",
         "[Events]", "Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text"]
t = 0.5
while t < 179:
    d = 1.8 + r.random() * 2
    lines.append(f"Dialogue: 0,{ts(t)},{ts(t+d)},Default,,0,0,0,,Line {int(t*10)} where the lanterns drift over the harbour")
    lines.append(f"Dialogue: 0,{ts(t+0.4)},{ts(t+d)},Default,,0,0,120,,{{\\i1}}and a second voice answers {int(t)}")
    t += d + 0.2
for k in range(0, 179, 6):
    x, y = r.randint(300, 1600), r.randint(200, 700)
    lines.append(f"Dialogue: 1,{ts(k)},{ts(k+5)},Sign,,0,0,0,,{{\\move({x},{y},{x+200},{y-80})\\blur3\\t(0,2000,\\frz15\\fscx130)\\fad(300,300)}}Lantern Street {k}")
for k in range(0, 179, 12):
    syl = "".join(f"{{\\k{r.randint(15,40)}}}la" for _ in range(14))
    lines.append(f"Dialogue: 2,{ts(k)},{ts(k+8)},Karaoke,,0,0,0,,{{\\blur1\\t(\\3c&H0000FF&)}}{syl}")
open(sys.argv[1], "w").write("\n".join(lines) + "\n")
PY
FONTS=(); total=0; i=0
while IFS= read -r f; do
  sz=$(stat -c %s "$f"); [ $((total + sz)) -gt 40000000 ] && continue
  FONTS+=(-attach "$f" -metadata:s:t:$i mimetype=application/x-truetype-font -metadata:s:t:$i "filename=$(basename "$f")")
  total=$((total + sz)); i=$((i+1))
done < <(find /usr/share/fonts -type f \( -name '*.ttf' -o -name '*.otf' \) -size +50k 2>/dev/null | sort)
echo "Lantern Festival: $i fonts attached ($((total / 1048576)) MB)"
ffmpeg -nostdin -y -loglevel error -f lavfi -i "testsrc2=duration=180:size=1920x1080:rate=24,noise=alls=10:allf=t" \
  -f lavfi -i "sine=frequency=520:duration=180" -f lavfi -i "sine=frequency=390:duration=180" -i "$TMP/lantern.ass" \
  -map 0 -map 1 -map 2 -map 3 \
  -c:v libx264 -preset veryfast -b:v 5M -maxrate 7M -bufsize 10M -pix_fmt yuv420p -x264-params keyint=240:min-keyint=240:scenecut=0 \
  -c:a:0 flac -ac:a:0 2 -c:a:1 aac -b:a:1 160k -ac:a:1 2 -c:s ass "${FONTS[@]}" \
  -metadata:s:a:0 language=jpn -metadata:s:a:1 language=eng -metadata:s:s:0 language=eng -metadata:s:s:0 "title=Signs & Songs" -disposition:s:0 default \
  "$D/Lantern Festival (2020).mkv"

# ---------- 4) 4K HDR10 HEVC Main10 (short) ----------
D="$OUT/movies/Ember Field (2024)"; mkdir -p "$D"
ffmpeg -nostdin -y -loglevel error -f lavfi -i "$(pattern 6 3840x2160 24)" -f lavfi -i "sine=frequency=250:duration=6" \
  -c:v libx265 -preset ultrafast -pix_fmt yuv420p10le -profile:v main10 \
  -x265-params "log-level=error:hdr10=1:colorprim=bt2020:transfer=smpte2084:colormatrix=bt2020nc:master-display=G(13250,34500)B(7500,3000)R(34000,16000)WP(15635,16450)L(10000000,1):max-cll=1000,400" \
  -color_primaries bt2020 -color_trc smpte2084 -colorspace bt2020nc -c:a eac3 -ac 6 \
  "$D/Ember Field (2024).mkv"

# ---------- 5) Needs server transcoding: MPEG-4 Part 2 + MP3 in AVI ----------
D="$OUT/movies/Old Reel (1999)"; mkdir -p "$D"
ffmpeg -nostdin -y -loglevel error -f lavfi -i "$(pattern 20 720x480 25)" -f lavfi -i "sine=frequency=800:duration=20" \
  -c:v mpeg4 -vtag XVID -q:v 5 -c:a libmp3lame -b:a 128k "$D/Old Reel (1999).avi"

# Chapter markers named like real anime releases, so the player can show intro/credits ranges in yellow.
cat > "$TMP/chapters.txt" <<'CH'
;FFMETADATA1
[CHAPTER]
TIMEBASE=1/1000
START=0
END=3000
title=Prologue
[CHAPTER]
TIMEBASE=1/1000
START=3000
END=8000
title=Opening
[CHAPTER]
TIMEBASE=1/1000
START=8000
END=16000
title=Part A
[CHAPTER]
TIMEBASE=1/1000
START=16000
END=20000
title=Ending
CH

# ---------- 6) Series: anime-style typesetting, HEVC Main10, 3 episodes ----------
for e in 1 2 3; do
  ffmpeg -nostdin -y -loglevel error -f lavfi -i "$(pattern 20 1920x1080 24)" -f lavfi -i "sine=frequency=$((300 + e * 50)):duration=20" -i "$TMP/anime.ass" -f ffmetadata -i "$TMP/chapters.txt" \
    -map 0 -map 1 -map 2 -map_chapters 3 -c:v libx265 -preset ultrafast -x265-params log-level=error -pix_fmt yuv420p10le -profile:v main10 \
    -c:a aac -c:s ass -attach "$FONT" -metadata:s:t:0 mimetype=application/x-truetype-font -metadata:s:t:0 filename=DejaVuSans-Bold.ttf \
    -metadata:s:a:0 language=jpn -metadata:s:s:0 language=eng -metadata:s:s:0 title="Signs & Songs" \
    -metadata title="Episode $e" "$OUT/tv/Skylark Isles/Season 01/Skylark Isles - S01E0$e.mkv"
done

# ---------- 6b) Non-anime series without chapters or markers: intros/credits found by listening ----------
# Three 4-minute episodes. Each opens with a different length of its own "story" sound (a cold open),
# then the same 30 s theme, more story, and the same 25 s of end-credits music. No chapters, no
# server segments: the only way to find the intro and credits is to match the sound across episodes.
W="$OUT/tv/Wavelength Street"; mkdir -p "$W/Season 02"
cat > "$W/tvshow.nfo" <<'NFO'
<?xml version="1.0" encoding="utf-8"?><tvshow><title>Wavelength Street</title><year>2021</year><genre>Drama</genre><genre>Comedy</genre><plot>A late-night radio station and the neighbours who keep calling in. Synthetic test series without chapters or intro markers.</plot></tvshow>
NFO
# Theme and credits music: fixed chord sequences (a new chord every 1/4 s), identical in every episode.
ffmpeg -nostdin -y -loglevel error -f lavfi -i "aevalsrc=exprs='0.45*sin(2*PI*(180+45*mod(floor(abs(sin(floor(t*4)*12.9898))*43758)\,30))*t)+0.3*sin(2*PI*(260+60*mod(floor(abs(sin(floor(t*4)*78.233))*43758)\,20))*t)':s=44100:d=30" -ac 2 "$TMP/theme.wav"
ffmpeg -nostdin -y -loglevel error -f lavfi -i "aevalsrc=exprs='0.45*sin(2*PI*(220+40*mod(floor(abs(sin(floor(t*3)*39.346))*43758)\,25))*t)+0.3*sin(2*PI*(330+55*mod(floor(abs(sin(floor(t*3)*11.135))*43758)\,18))*t)':s=44100:d=25" -ac 2 "$TMP/credits.wav"
story() { # seconds seed: speech-like sound that differs every episode (a tone that jumps 5×/s, plus hiss)
  ffmpeg -nostdin -y -loglevel error -f lavfi -i "aevalsrc=exprs='0.35*sin(2*PI*(150+900*abs(sin(floor(t*5)*($2+3.7)*91.3)))*t)+0.08*(2*random(0)-1)':s=44100:d=$1" -ac 2 "$3"
}
names=("" "Night Shift" "Overnight" "Relay")
opens=(0 20 8 25)
for e in 1 2 3; do
  o=${opens[$e]}; body=$((240 - o - 30 - 25))
  story "$o" "$e" "$TMP/open$e.wav"; story "$body" "$((e + 10))" "$TMP/body$e.wav"
  ffmpeg -nostdin -y -loglevel error -f lavfi -i "testsrc2=duration=240:size=640x360:rate=25" \
    -i "$TMP/open$e.wav" -i "$TMP/theme.wav" -i "$TMP/body$e.wav" -i "$TMP/credits.wav" \
    -filter_complex "[1:a][2:a][3:a][4:a]concat=n=4:v=0:a=1[a]" -map 0:v -map "[a]" \
    -c:v libx264 -preset ultrafast -pix_fmt yuv420p -c:a aac -b:a 128k -metadata title="${names[$e]}" \
    "$W/Season 02/Wavelength Street - S02E0$e.mkv"
done

# ---------- 6b) A live-action show whose closing credits look alike but sound different ----------
# White text rolling up a black screen at the end of every episode, over music that changes every
# episode (so listening can't find it), and in episode 2 a post-credits scene after them. Exercises
# the on-screen credits check (trickplay thumbnails) and Skip Outro landing on the post-credits scene.
H="$OUT/tv/Harbor Precinct"; mkdir -p "$H/Season 01"
cat > "$H/tvshow.nfo" <<'NFO'
<?xml version="1.0" encoding="utf-8"?><tvshow><title>Harbor Precinct</title><year>2019</year><genre>Crime</genre><genre>Drama</genre><plot>Detectives on the night shift at a waterfront station. Synthetic live-action-style test series: closing credits on black, different music every episode.</plot></tvshow>
NFO
for i in $(seq 1 60); do echo "Role $i ........ Actor Name $i"; done > "$TMP/credits.txt"
for e in 1 2 3; do
  tag=$([ "$e" = 2 ] && echo 20 || echo 0)
  ffmpeg -nostdin -y -loglevel error -f lavfi -i "testsrc2=duration=170:size=640x360:rate=25" -c:v libx264 -preset ultrafast -pix_fmt yuv420p "$TMP/hp_body.mp4"
  ffmpeg -nostdin -y -loglevel error -f lavfi -i "color=c=black:size=640x360:rate=25:duration=45" \
    -vf "drawtext=fontfile=$FONT:textfile=$TMP/credits.txt:fontcolor=white:fontsize=18:line_spacing=10:x=(w-tw)/2:y=h-t*45" -c:v libx264 -preset ultrafast -pix_fmt yuv420p "$TMP/hp_credits.mp4"
  parts=("$TMP/hp_body.mp4" "$TMP/hp_credits.mp4")
  if [ "$tag" -gt 0 ]; then
    ffmpeg -nostdin -y -loglevel error -f lavfi -i "testsrc=duration=$tag:size=640x360:rate=25" -c:v libx264 -preset ultrafast -pix_fmt yuv420p "$TMP/hp_tag.mp4"
    parts+=("$TMP/hp_tag.mp4")
  fi
  : > "$TMP/hp_list.txt"; for f in "${parts[@]}"; do echo "file '$f'" >> "$TMP/hp_list.txt"; done
  ffmpeg -nostdin -y -loglevel error -f concat -safe 0 -i "$TMP/hp_list.txt" -c copy "$TMP/hp_video.mp4"
  story $((215 + tag)) "$((e + 40))" "$TMP/hp_audio.wav"
  ffmpeg -nostdin -y -loglevel error -i "$TMP/hp_video.mp4" -i "$TMP/hp_audio.wav" -map 0:v -map 1:a -shortest \
    -c:v libx264 -preset ultrafast -pix_fmt yuv420p -c:a aac -b:a 96k -metadata title="Case $e" \
    "$H/Season 01/Harbor Precinct - S01E0$e.mkv"
done

# ---------- 7) Dolby Vision: profile 8.1 (HDR10 base), 5 (no base layer), 7 (UHD Blu-ray) ----------
# Needs dovi_tool + mkvmerge (CI installs both); skipped otherwise. mkvmerge writes the DV
# configuration record from the RPUs, which is what Jellyfin reads to classify the range type.
if command -v dovi_tool >/dev/null && command -v mkvmerge >/dev/null; then
  HERE=$(cd "$(dirname "$0")" && pwd)
  set +e
  (
    set -e
    FRAMES=72 # 3 s at 24 fps
    ffmpeg -nostdin -y -loglevel error -f lavfi -i "$(pattern 3 1920x1080 24)" \
      -c:v libx265 -preset ultrafast -pix_fmt yuv420p10le -profile:v main10 \
      -x265-params "log-level=error:hdr10=1:colorprim=bt2020:transfer=smpte2084:colormatrix=bt2020nc:master-display=G(13250,34500)B(7500,3000)R(34000,16000)WP(15635,16450)L(10000000,1):max-cll=1000,400" \
      -f hevc "$TMP/dv_base.hevc"
    ffmpeg -nostdin -y -loglevel error -f lavfi -i "sine=frequency=520:duration=3" -c:a eac3 -ac 6 "$TMP/dv_audio.mka"
    cat > "$TMP/p81.json" <<JSON
{ "cm_version": "V40", "profile": "8.1", "length": $FRAMES,
  "level6": { "max_display_mastering_luminance": 1000, "min_display_mastering_luminance": 1, "max_content_light_level": 1000, "max_frame_average_light_level": 400 } }
JSON
    dovi_tool generate -j "$TMP/p81.json" -o "$TMP/p81.rpu" >/dev/null
    for i in $(seq $FRAMES); do cat "$HERE/dovi/profile5.rpu"; done > "$TMP/p5.rpu"
    for i in $(seq $FRAMES); do cat "$HERE/dovi/profile7-fel.rpu"; done > "$TMP/p7.rpu"
    dv_movie() { # rpu title
      local d="$OUT/movies/$2"; mkdir -p "$d"
      dovi_tool inject-rpu -i "$TMP/dv_base.hevc" --rpu-in "$1" -o "$TMP/dv.hevc" >/dev/null
      mkvmerge -q -o "$d/$2.mkv" --default-duration 0:24fps "$TMP/dv.hevc" --language 0:eng "$TMP/dv_audio.mka"
      dovi_tool extract-rpu -i "$TMP/dv.hevc" -o "$TMP/check.rpu" >/dev/null && \
        echo "== $2: $(dovi_tool info -i "$TMP/check.rpu" --summary 2>&1 | tr '\n' ' ' | cut -c1-300)" >&2 || true
    }
    dv_movie "$TMP/p81.rpu" "Prism Coast (2025)"
    dv_movie "$TMP/p5.rpu" "Neon Tide (2025)"
    dv_movie "$TMP/p7.rpu" "Velvet Static (2025)"
  )
  rc=$?
  set -e
  if [ $rc -ne 0 ]; then
    echo "::warning::Dolby Vision sample generation failed (exit $rc); DV samples skipped" >&2
    rm -rf "$OUT/movies/Prism Coast (2025)" "$OUT/movies/Neon Tide (2025)" "$OUT/movies/Velvet Static (2025)"
  fi
else
  echo "dovi_tool/mkvmerge not found: Dolby Vision samples skipped" >&2
fi

rm -rf "$TMP"
find "$OUT" -type f | sort
